{
  "title": "Tính thể tích khối cầu và diện tích hình tròn thiết diện",
  "description": "Bài toán này minh họa cách dựng một khối cầu từ tâm và một điểm trên mặt, sau đó cắt khối cầu bằng một mặt phẳng để tạo ra một đường tròn thiết diện, và cuối cùng là tính toán thể tích khối cầu và diện tích hình tròn thiết diện.",
  "memory_declarations": [
    {
      "name": "I",
      "type": "point3",
      "initial_value": [0, 0, 0],
      "source_fact_id": "tam_s"
    },
    {
      "name": "A",
      "type": "point3",
      "initial_value": [15, 0, 0],
      "source_fact_id": "diem_a_tren_s"
    },
    {
      "name": "S",
      "type": "curved_solid",
      "source_fact_id": "cat_cau_tao_tron"
    },
    {
      "name": "C",
      "type": "circle3",
      "source_fact_id": "cat_cau_tao_tron"
    },
    {
      "name": "the_tich_s",
      "type": "float"
    },
    {
      "name": "dien_tich_c",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "I",
      "at": [0, 0, 0],
      "source_fact_id": "tam_s",
      "label": "Tâm mặt cầu (S)"
    },
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [15, 0, 0],
      "source_fact_id": "diem_a_tren_s",
      "label": "Điểm A thuộc mặt cầu (S)"
    },
    {
      "kind": "construct_plane_from_equation",
      "target_var": "P",
      "a": 0,
      "b": 0,
      "c": 1,
      "d": -9,
      "source_fact_id": "mat_phang_p",
      "label": "Mặt phẳng (P): z = 9"
    },
    {
      "kind": "construct_curved_solid",
      "target_var": "S",
      "curved_kind": "ball",
      "anchor": "I",
      "rim_point": "A",
      "label": "Mặt cầu (S) tâm I, đi qua A"
    },
    {
      "kind": "assign",
      "target_var": "C",
      "expr": {
        "kind": "intersect_plane_curved",
        "solid": "S",
        "plane": "P"
      },
      "label": "Đường tròn (C) là giao của (S) và (P)"
    },
    {
      "kind": "assign",
      "target_var": "the_tich_s",
      "expr": {
        "kind": "measure",
        "quantity": "volume",
        "of": "S"
      }
    },
    {
      "kind": "assign",
      "target_var": "dien_tich_c",
      "expr": {
        "kind": "measure",
        "quantity": "area",
        "of": "C"
      }
    }
  ],
  "pedagogical_intent": "Chương trình này minh họa cách dựng một khối cầu và một mặt phẳng, sau đó tìm thiết diện là một đường tròn và tính toán các đại lượng liên quan. Nó cho thấy mối quan hệ hình học giữa khối cầu và mặt phẳng cắt."
}
